'use strict';
const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict');
const base='releases/v402',dest='qa/fgts-v404-candidate',sha=x=>crypto.createHash('sha256').update(x).digest('hex');
assert(!fs.existsSync(dest),'candidate destination must be new');
const current=fs.readFileSync('mobile/current.json'),manifest=JSON.parse(fs.readFileSync(base+'/manifest.json'));
for(const [name,hash] of Object.entries(manifest.files))assert.equal(sha(fs.readFileSync(base+'/'+name)),hash,'base '+name);
const protectedFiles=Object.fromEntries(fs.readdirSync(base).map(n=>[n,sha(fs.readFileSync(base+'/'+n))]));
fs.cpSync(base,dest,{recursive:true});
const file=dest+'/lts-v384-startup-1.js',original=fs.readFileSync(file,'utf8');
const extracted=fs.readFileSync('.github/fixtures/fgts-dashboard/fixture-runtime.js','utf8'),helper=extracted.slice(0,extracted.indexOf('  function dashboard178(){'));
const anchor="   kpi(root,'FGTS',c?.fgts,'Recurso restrito');";
assert.equal(original.split(anchor).length,2);assert.equal(original.split('  function dashboard178(){').length,2);
fs.writeFileSync(file,original.replace('  function dashboard178(){',helper+'  function dashboard178(){').replace(anchor,"   const fgtsPosition=dashboardFgtsPosition(state.wealth.status==='ready'?state.wealth.data:null);\n   kpi(root,'FGTS',fgtsPosition.balance,fgtsPosition.note);"));
fs.writeFileSync(dest+'/app.html',fs.readFileSync(base+'/app.html','utf8').replaceAll('V402','V404').replace('v402-daily-cofrinho-20261102','v404-fgts-evidence-candidate'));
const provenance={release:'v404',base_release:'v402',candidate_only:true,scope:'FGTS dashboard documentary evidence presentation',protected_base_files:protectedFiles,original_financial_sources_changed:false,original_cash_forecasts_changed:false,private_http_validated:false,physical_mobile_validated:false};
fs.writeFileSync(dest+'/provenance.json',JSON.stringify(provenance,null,2)+'\n');
fs.writeFileSync(dest+'/manifest.json',JSON.stringify({release:'v404',base_release:'v402',entry:'app.html',files:Object.fromEntries(fs.readdirSync(dest).filter(n=>n!=='manifest.json').sort().map(n=>[n,sha(fs.readFileSync(dest+'/'+n))])),protected_manifest:{path:base+'/manifest.json',sha256:protectedFiles['manifest.json']}},null,2)+'\n');
for(const [name,hash] of Object.entries(protectedFiles))assert.equal(sha(fs.readFileSync(base+'/'+name)),hash,'immutable '+name);
for(const name of fs.readdirSync(base))if(!['app.html','manifest.json','provenance.json','lts-v384-startup-1.js'].includes(name))assert.equal(sha(fs.readFileSync(dest+'/'+name)),protectedFiles[name],'preserved '+name);
assert.equal(sha(fs.readFileSync('mobile/current.json')),sha(current));
console.log(JSON.stringify({pass:true,candidate:'v404',candidate_path:dest,v402_unchanged:true,mobile_unchanged:true,files:fs.readdirSync(dest).length}));
